import 'package:fpdart/fpdart.dart';

import '../../../../core/failure/failure.dart';
import '../entities/entries_page.dart';
import '../entities/entry.dart';

/// The port later epics extend (Code Map) — `features/capture/` depends on
/// this abstract class only, never `entries/data` or `entries/presentation`
/// (RNF06).
abstract class EntriesRepository {
  /// Posts to `entries-create` (`ApiClient.post`, via
  /// `EntriesRemoteDataSource`) and, on success, writes the entry through
  /// to the `entries` Hive box before returning `Right` (Boundaries) — a
  /// caller that only reads the returned [Entry] never needs to touch the
  /// box itself. Every [Failure] — including
  /// [Failure.networkOffline] — is returned as `Left`, unmapped and
  /// un-retried; the caller decides what to do with it (RNF09).
  Future<Either<Failure, Entry>> create({
    required String content,
    required EntrySource source,
    int? mediaDurationSeconds,
  });

  /// Calls `entries-list` (`ApiClient.get`, via
  /// `EntriesRemoteDataSource`), newest-first by `occurredAt` — server
  /// behavior assumed, undocumented (Code Map, decided per AGENTS.md
  /// policy: "where `docs/input/` is silent... decide and proceed").
  ///
  /// On [Failure.networkOffline]/[Failure.networkTimeout] specifically,
  /// falls back to a full dump of the `entries` Hive box, sorted
  /// `occurredAt` desc, with `EntriesPage.nextCursor: null` (Boundaries) —
  /// every *other* [Failure] (e.g. [Failure.authExpired]) propagates as
  /// `Left`, unmapped (RNF09).
  ///
  /// A successful page persists every item to the `entries` Hive box
  /// *before* returning `Right` — same "persist then return" ordering
  /// [create] already uses.
  Future<Either<Failure, EntriesPage>> list({String? cursor, int limit = 20});

  /// spec-4-4 (RF07) — this repository's third and last method (Boundaries:
  /// "create+read only, forever"). Calls `entries-get` (`ApiClient.get`,
  /// via `EntriesRemoteDataSource`) with [id] as the one path parameter,
  /// then persists the fetched entry to the `entries` Hive box (`put`)
  /// *before* returning `Right` — same "persist then return" ordering
  /// [create]/[list] already use.
  ///
  /// On [Failure.networkOffline]/[Failure.networkTimeout] specifically,
  /// falls back to `entriesBox.get(id)` if present; a cache miss propagates
  /// the original failure unchanged (no synthesized not-found — that
  /// distinction belongs to whichever `Failure` the backend/network
  /// actually produced). Every *other* [Failure] — including
  /// [Failure.notFound] for an id that never existed or belongs to another
  /// user — is returned as `Left`, unmapped (RNF09); RNF04 (identical
  /// treatment for both causes) is the caller's own rendering job, never
  /// this repository's.
  Future<Either<Failure, Entry>> getById(String id);
}

/// `POST /entries`'s four possible origins (`openapi.yaml:345-351`). This
/// story only ever produces [manual] (Boundaries: "source=manual for this
/// story") — the other three exist here already so the port
/// ([EntriesRepository.create]) doesn't need to change shape when Stories
/// 3.2/3.3 (audio/photo) and RF10 (chat) start passing them.
enum EntrySource { manual, audio, photo, chat }

/// A saved journal entry — plain `{id, content, source, chatMessageId,
/// occurredAt, serverRevision, createdAt, updatedAt, mediaDurationSeconds}`
/// class, no `freezed` (mirrors `AuthenticatedUser`: this feature has no
/// need for the union/copyWith machinery `Failure` uses). Boundaries:
/// never a field beyond this exact set — `tags`/`piiStatus`/`piiSpans`/
/// `embeddingStatus` still belong to later epics, not this story.
/// [mediaDurationSeconds] was the one field Story 3.1 deferred (its own
/// comment named it "later epics") — spec-3-2 is that story, for the
/// `source: audio` entries it produces.
///
/// [occurredAt]/[createdAt]/[updatedAt] are kept as the backend's own ISO
/// 8601 strings rather than parsed into `DateTime` on this entity itself —
/// spec-4-1's `groupEntriesByDate()`/`EntryRecordCard`'s own time label
/// each parse [occurredAt] at their own call site instead, so a malformed
/// string only ever risks throwing at the one place that actually needs
/// the parsed value, never here.
class Entry {
  const Entry({
    required this.id,
    required this.content,
    required this.source,
    required this.chatMessageId,
    required this.occurredAt,
    required this.serverRevision,
    required this.createdAt,
    required this.updatedAt,
    this.mediaDurationSeconds,
  });

  final String id;
  final String content;
  final EntrySource source;

  /// Non-null only for a [EntrySource.chat]-sourced entry (RF10) — always
  /// `null` for this story's [EntrySource.manual] entries.
  final String? chatMessageId;
  final String occurredAt;
  final int serverRevision;
  final String createdAt;
  final String updatedAt;

  /// Non-null only for an [EntrySource.audio]-sourced entry
  /// (`AudioEntryCubit.save()`) — `null` for every other source.
  final int? mediaDurationSeconds;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Entry &&
          other.id == id &&
          other.content == content &&
          other.source == source &&
          other.chatMessageId == chatMessageId &&
          other.occurredAt == occurredAt &&
          other.serverRevision == serverRevision &&
          other.createdAt == createdAt &&
          other.updatedAt == updatedAt &&
          other.mediaDurationSeconds == mediaDurationSeconds);

  @override
  int get hashCode => Object.hash(
    id,
    content,
    source,
    chatMessageId,
    occurredAt,
    serverRevision,
    createdAt,
    updatedAt,
    mediaDurationSeconds,
  );

  @override
  String toString() =>
      'Entry(id: $id, content: $content, source: $source, '
      'chatMessageId: $chatMessageId, occurredAt: $occurredAt, '
      'serverRevision: $serverRevision, createdAt: $createdAt, '
      'updatedAt: $updatedAt, '
      'mediaDurationSeconds: $mediaDurationSeconds)';
}

