24	/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
25	/// newest-first, grouped by day, each card marked by origin. Replaces the
26	/// former `MeusRegistrosPlaceholderScreen`.
27	///
28	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
29	/// closes it (`BlocProvider.value`, same convention
30	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
31	/// this screen's own [ScrollController] is this `State`'s to dispose.
32	///
33	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
34	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
35	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
36	/// rebuilt from scratch underneath it, so [_scrollController]'s position
37	/// and [cubit]'s state survive that overlay appearing with no extra code
38	/// needed here (Acceptance Criteria's third bullet).
39	class MeusRegistrosScreen extends StatefulWidget {
40	  const MeusRegistrosScreen({required this.cubit, super.key});
41	
42	  final MeusRegistrosCubit cubit;
43	
44	  @override
45	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
46	}
47	
48	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
49	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
50	  // `BootSplashScreen`.
51	  static const _skeletonThreshold = Duration(milliseconds: 300);
52	
53	  final ScrollController _scrollController = ScrollController();
54	  Timer? _skeletonTimer;
55	  bool _showSkeleton = false;
56	
57	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
58	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
59	  /// detail-route instances); cleared once the pushed route is popped, via
60	  /// `whenComplete` below.
61	  bool _navigatingToDetail = false;
62	
63	  @override
64	  void initState() {
65	    super.initState();
66	    widget.cubit.loadFirstPage();
67	    _skeletonTimer = Timer(_skeletonThreshold, () {
68	      if (mounted) {
69	        setState(() => _showSkeleton = true);
70	      }
71	    });
72	    _scrollController.addListener(_onScroll);
73	  }
74	
75	  @override
76	  void dispose() {
77	    _skeletonTimer?.cancel();
78	    _scrollController
79	      ..removeListener(_onScroll)
80	      ..dispose();
81	    super.dispose();
82	  }
83	
84	  void _openDetail(Entry entry) {
85	    if (_navigatingToDetail) {
86	      return;
87	    }
88	    _navigatingToDetail = true;
89	    context
90	        .push(
91	          '${AppRoutePaths.meusRegistros}/'
92	          '${Uri.encodeComponent(entry.id)}',
93	        )
94	        .whenComplete(() {
95	          if (mounted) {
96	            setState(() => _navigatingToDetail = false);
97	          } else {
98	            _navigatingToDetail = false;
99	          }
100	        });
101	  }
102	
103	  void _onScroll() {
104	    if (!_scrollController.hasClients) {
105	      return;
106	    }
107	    final position = _scrollController.position;
108	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
109	    // purely as a scroll-distance buffer, not a new literal) for a
110	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
111	    // there's no further page or a call is already in flight.
112	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
113	      widget.cubit.loadMore();
114	    }
115	  }
116	
117	  @override
118	  Widget build(BuildContext context) {
119	    return BlocProvider.value(
120	      value: widget.cubit,
121	      child: Scaffold(
122	        backgroundColor: DesignTokens.colorSurfaceBg,
123	        body: Column(
124	          children: [
125	            const BackArrowHeader(title: 'Meus Registros'),
126	            Expanded(
127	              child: BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
128	                builder: (context, state) => switch (state) {
129	                  MeusRegistrosLoading() =>
130	                    _showSkeleton
131	                        ? const _SkeletonList()
132	                        : const SizedBox.shrink(),
133	                  MeusRegistrosEmpty() => const _EmptyState(),
134	                  MeusRegistrosError(message: final message) => _ErrorState(
135	                    message: message,
136	                    onRetry: widget.cubit.loadFirstPage,
137	                  ),
138	                  MeusRegistrosLoaded() => _EntryList(
139	                    state: state,
140	                    scrollController: _scrollController,
141	                    onRetryLoadMore: widget.cubit.retryLoadMore,
142	                    onRetryTap: (entry) => widget.cubit.retry(entry.id),
143	                    onCardTap: _openDetail,
144	                  ),
145	                },
146	              ),
147	            ),
148	          ],
149	        ),
150	      ),
151	    );
152	  }
153	}
154	
155	class _SkeletonList extends StatelessWidget {
156	  const _SkeletonList();
157	
158	  // Not a real count of anything server-sent — just enough placeholder
159	  // cards to fill a typical screen while the first page is in flight.
160	  static const _placeholderCount = 4;
161	
162	  @override
163	  Widget build(BuildContext context) {
164	    return ListView.builder(
165	      padding: DesignTokens.screenPadding,
166	      itemCount: _placeholderCount,
167	      itemBuilder: (context, index) => Padding(
168	        padding: const EdgeInsets.only(bottom: DesignTokens.spacingSm),
169	        child: const EntrySkeletonCard(),
170	      ),
171	    );
172	  }
173	}
174	
175	class _EmptyState extends StatelessWidget {
176	  const _EmptyState();
177	
178	  @override
179	  Widget build(BuildContext context) {
180	    // Tela 4 — Vazio: icon + copy + a primary CTA that opens the same
181	    // Insertion Modal the Home/Chat "+" FAB opens (`placeholder_screens.
182	    // dart`'s own call shape, mirrored verbatim) — spec-4-3.
183	    return Center(
184	      child: Padding(
