186	          vertical: DesignTokens.entriesEmptyStateVerticalPadding,
187	          horizontal: DesignTokens.spacingLg,
188	        ),
189	        child: Column(
190	          mainAxisSize: MainAxisSize.min,
191	          children: [
192	            const Icon(
193	              Icons.menu_book_outlined,
194	              size: DesignTokens.entriesEmptyStateIconSize,
195	              color: DesignTokens.colorBorder,
196	            ),
197	            const SizedBox(height: DesignTokens.spacingMd),
198	            Text(
199	              'Nenhum registro ainda',
200	              style: DesignTokens.textBodyMd.copyWith(
201	                color: DesignTokens.colorTextSecondary,
202	              ),
203	            ),
204	            const SizedBox(height: DesignTokens.spacingMd),
205	            AppButton(
206	              label: 'Criar primeiro registro',
207	              onPressed: () => InsertionModal.show(
208	                context,
209	                cubit: sl<TextEntryCubit>(),
210	                audioCubit: sl<AudioEntryCubit>(),
211	                photoCubit: sl<PhotoEntryCubit>(),
212	              ),
213	            ),
214	          ],
215	        ),
216	      ),
217	    );
218	  }
219	}
220	
221	class _ErrorState extends StatelessWidget {
222	  const _ErrorState({required this.message, required this.onRetry});
223	
224	  final String message;
225	  final VoidCallback onRetry;
226	
227	  @override
228	  Widget build(BuildContext context) {
229	    return Center(
230	      child: Padding(
231	        padding: DesignTokens.screenPadding,
232	        child: Column(
233	          mainAxisSize: MainAxisSize.min,
234	          children: [
235	            Text(
236	              message,
237	              textAlign: TextAlign.center,
238	              style: DesignTokens.textBodyMd.copyWith(
239	                color: DesignTokens.colorTextPrimary,
240	              ),
241	            ),
242	            const SizedBox(height: DesignTokens.spacingMd),
243	            TextButton(
244	              onPressed: onRetry,
245	              child: Text(
246	                'Tentar novamente',
247	                style: DesignTokens.textLabelMd.copyWith(
248	                  color: DesignTokens.colorPrimary,
249	                ),
250	              ),
251	            ),
252	          ],
253	        ),
254	      ),
255	    );
256	  }
257	}
258	
259	class _EntryList extends StatelessWidget {
260	  const _EntryList({
261	    required this.state,
262	    required this.scrollController,
263	    required this.onRetryLoadMore,
264	    required this.onRetryTap,
265	    required this.onCardTap,
266	  });
267	
268	  final MeusRegistrosLoaded state;
269	  final ScrollController scrollController;
270	  final VoidCallback onRetryLoadMore;
271	  final void Function(Entry entry) onRetryTap;
272	
273	  /// spec-4-4 — opens `EntryDetailScreen` for the tapped card.
274	  final void Function(Entry entry) onCardTap;
275	
276	  @override
277	  Widget build(BuildContext context) {
278	    final groups = state.groups;
279	    // A non-empty `state.entries` can still yield zero groups if every one
280	    // of its `occurredAt` values is malformed (`groupEntriesByDate()` skips
281	    // rather than throws) — fall back to the same plain empty-state text
282	    // rather than rendering a ListView with nothing visibly in it.
283	    if (groups.isEmpty) {
284	      return const _EmptyState();
285	    }
286	    return ListView.builder(
287	      controller: scrollController,
288	      padding: DesignTokens.screenPadding,
289	      itemCount: groups.length + 1,
290	      itemBuilder: (context, index) {
291	        if (index == groups.length) {
292	          return _LoadMoreFooter(
293	            hasMore: state.nextCursor != null,
294	            isLoading: state.isLoadingMore,
295	            failed: state.loadMoreFailed,
